export const UPDATE_ROOT='https://babycrttv.github.io/tileforge-studio/';
export function releaseVersion(v){if(typeof v!=='string'||!/^\d{1,5}\.\d{1,5}\.\d{1,5}$/.test(v))throw Error('Invalid release version');return v;}
export function newerVersion(a,b){const x=releaseVersion(a).split('.').map(Number),y=releaseVersion(b).split('.').map(Number);for(let i=0;i<3;i++)if(x[i]!==y[i])return x[i]>y[i];return false;}
export function validateRelease(data){
 if(!data||data.format!=='tileforge-update')throw Error('Update information is not ready. Try again shortly.');
 const version=releaseVersion(data.version),apk=data.android;
 if(!Number.isInteger(data.versionCode)||data.versionCode<1||!apk||apk.packageId!=='com.eightbittrade.tileforge'||apk.url!==UPDATE_ROOT+'downloads/TileForge-Studio-'+version+'.apk'||!Number.isSafeInteger(apk.size)||apk.size<1||apk.size>100*1024*1024||typeof apk.sha256!=='string'||!/^[a-f\d]{64}$/i.test(apk.sha256))throw Error('The update information is incomplete. Try again later.');
 return {version,versionCode:data.versionCode,android:{...apk},notes:Array.isArray(data.notes)?data.notes.filter(n=>typeof n==='string').slice(0,8).map(n=>n.slice(0,300)):[]};
}
const STATUSES=new Set(['idle','checking','current','available','downloading','ready','permission','installing','error']);
export function updateState(s={}){const v=value=>{try{return releaseVersion(value);}catch{return '';}};return {status:STATUSES.has(s.status)?s.status:'idle',installedVersion:v(s.installedVersion),latestVersion:v(s.latestVersion),message:String(s.message||'').slice(0,800),notes:String(s.notes||'').slice(0,2500),progress:Math.min(100,Math.max(0,Math.round(Number(s.progress)||0))),available:s.available===true,downloaded:s.downloaded===true,checkedAt:Number.isFinite(s.checkedAt)?s.checkedAt:0};}
export function createSettings({$,version,beforeUpdate,fetchRelease=fetch,native=window.TileForgeUpdates,reload=url=>location.replace(url)}){
 const desktop=new URLSearchParams(location.search).has('desktop');const android=typeof native?.getState==='function'&&typeof native?.check==='function'&&typeof native?.download==='function'&&typeof native?.install==='function';
 let state=updateState({installedVersion:version,message:'Check for the latest TileForge update.'}),release=null,applying=false;
 const dialog=document.createElement('dialog');dialog.id='settingsDialog';dialog.className='settings-dialog';dialog.setAttribute('aria-labelledby','settingsTitle');
 dialog.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">TILEFORGE STUDIO</span><h2 id="settingsTitle">Settings</h2></div><button id="closeSettings" aria-label="Close settings">×</button></div><h3>App updates</h3><dl class="update-versions"><dt>Current version</dt><dd id="updateInstalled"></dd><dt>Latest version</dt><dd id="updateLatest">Not checked</dd><dt>Last checked</dt><dd id="updateChecked">Not yet</dd></dl><p id="updateStatus" role="status" aria-live="polite"></p><progress id="updateProgress" max="100" value="0" aria-label="Update download progress" hidden></progress><p id="updateNotes" class="update-notes" hidden></p><div class="update-actions"><button id="checkAppUpdates">Check for updates</button><button id="applyAppUpdate" class="primary" hidden>Download and install update</button></div><p id="updateExplanation" class="studio-note"></p><p class="studio-note">Your current workspace is saved as a draft before updating. Keep portable project backups too.</p><a href="${UPDATE_ROOT}" target="_blank" rel="noopener">Official downloads ↗</a>`;
 document.body.append(dialog);const id=n=>dialog.querySelector('#'+n);
 id('updateExplanation').textContent=desktop?'Windows updates open the official release page after saving your draft. Download and run the new installer; your application data stays on this device.':android?'The APK downloads inside TileForge. Android asks you to confirm installation and may ask you to allow updates from this app. Your drafts and settings stay in place.':'The web app checks the same release information. Apply update saves your workspace as a draft and refreshes the editor. Android APK installation is available in the installed app.';
 function render(){const busy=['checking','downloading','installing','permission'].includes(state.status)||applying;id('updateInstalled').textContent=state.installedVersion||version;id('updateLatest').textContent=state.latestVersion||'Not checked';id('updateChecked').textContent=state.checkedAt?new Date(state.checkedAt).toLocaleString():'Not yet';id('updateStatus').textContent=state.message;id('updateNotes').textContent=state.notes;id('updateNotes').hidden=!state.notes;id('checkAppUpdates').disabled=busy;id('applyAppUpdate').hidden=!state.available;id('applyAppUpdate').disabled=busy;id('applyAppUpdate').textContent=android?(state.downloaded?'Install update':'Download and install update'):desktop?'Open Windows update':'Apply web update';id('updateProgress').hidden=!['downloading','ready','permission','installing'].includes(state.status);id('updateProgress').value=state.progress;}
 async function check(){
  if(android){state={...state,status:'checking',available:false,downloaded:false,message:'Checking for updates…'};render();try{native.check();}catch{state={...state,status:'error',message:'Could not start the update check. Please try again.'};render();}return;}
  state={...state,status:'checking',available:false,latestVersion:'',notes:'',message:'Checking for updates…'};release=null;render();const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),15000);
  try{const r=await fetchRelease(UPDATE_ROOT+'update.json?t='+Date.now(),{cache:'no-store',signal:abort.signal});if(!r.ok)throw Error('Could not reach the update server. Please try again later.');const text=await r.text();if(text.length>65536)throw Error('Update information is too large.');release=validateRelease(JSON.parse(text));const available=newerVersion(release.version,version);state={...state,status:available?'available':'current',latestVersion:release.version,available,checkedAt:Date.now(),notes:release.notes.join('\n'),message:available?'TileForge '+release.version+' is available.':'You are using the latest web version.'};}catch(e){state={...state,status:'error',available:false,message:e.name==='AbortError'?'The update check timed out. Check your connection and try again.':e.message||'Could not check for updates. Please try again.'};}finally{clearTimeout(timeout);render();}
 }
 id('closeSettings').onclick=()=>dialog.close();$('settingsBtn').onclick=()=>{if(android)try{state=updateState(JSON.parse(native.getState()));}catch{}render();dialog.showModal();};id('checkAppUpdates').onclick=check;
 id('applyAppUpdate').onclick=async()=>{
  if(applying||!state.available)return;applying=true;render();
  try{await beforeUpdate();if(desktop){window.open('https://github.com/BabyCRTTV/tileforge-studio/releases/tag/windows-v'+release.version,'_blank');return;}if(android){if(state.downloaded)native.install();else native.download();}else{
    // Network-first assets carry release queries; refresh only after the new entry is reachable.
    const url=new URL('editor.html',location.href);url.searchParams.set('update',release.version);const r=await fetchRelease(url.href,{cache:'no-store'});if(!r.ok)throw Error('The new web editor is not ready yet. Please try again shortly.');const html=await r.text();if(!html.includes('app.mjs?v='+release.version))throw Error('The new web editor is still being published. Please try again shortly.');
    const registration=await navigator.serviceWorker?.getRegistration();if(registration){await registration.update();registration.waiting?.postMessage({type:'SKIP_WAITING'});}reload(url.href);
  }}catch(e){state={...state,status:'error',message:'Update paused: '+(e.message||'please try again')+'. Export your project if draft storage is unavailable.'};}finally{applying=false;render();}
 };
 window.addEventListener('tileforge:update',e=>{if(!android)return;state=updateState(e.detail);render();});render();return {check};
}
